\copy (SELECT d.name AS district, p.category, p.role, p.osm_type, p.osm_id, p.name, p.osm_key, p.osm_value, round(ST_Y(p.geom)::numeric, 6) AS lat, round(ST_X(p.geom)::numeric, 6) AS lon, p.on_boundary, p.possible_duplicate FROM (SELECT poi.*, row_number() OVER (PARTITION BY district_id, category ORDER BY osm_id) AS rn FROM poi) AS p JOIN district AS d ON d.id = p.district_id WHERE p.rn <= 2 ORDER BY d.name, p.category, p.osm_id) TO 'data/samples/poi.tsv' WITH (FORMAT csv, HEADER true, DELIMITER E'\t')
